import{_ as a,o as i,c as r,a2 as t}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Magery overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/magic/overview.md","filePath":"guide/magic/overview.md"}'),n={name:"guide/magic/overview.md"};function s(o,e,l,d,c,m){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="magery-overview" tabindex="-1">Magery overview <a class="header-anchor" href="#magery-overview" aria-label="Permalink to &quot;Magery overview&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><p><a href="/Syrolands-Public/game-design/magic.html">Full design specification</a></p><p>Magery describes how well you execute magical patterns; it does not automatically teach every spell. In the proposal, your world discoveries determine what you know, practice deepens individual spells and preparation determines what is ready under pressure.</p><p>A spell has a stable Core Pattern and may accept compatible learned glyphs with trade-offs. This is a bounded system, not an unrestricted spell builder. Ordinary casting still takes its normal time and resources, even for memorized spells.</p><p>Reaching Magery 100 would mean technical mastery, not magical completion. Rare patterns, schools, modifiers, Familiarity, better preparation, grimoires, rituals, regional knowledge, player skill, rare reagents and Inscription provide longer-term goals under the proposed no-ordinary-120 direction.</p><p><a href="/Syrolands-Public/guide/magic/learning-spells.html">Learning spells</a> · <a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Memory and Familiarity</a> · <a href="/Syrolands-Public/guide/magic/variants-and-glyphs.html">Variants</a> · <a href="/Syrolands-Public/guide/magic/meditation-and-concentration.html">Meditation and Concentration</a> · <a href="/Syrolands-Public/guide/magic/spellbooks-scrolls-and-reagents.html">Books, scrolls and reagents</a> · <a href="/Syrolands-Public/guide/professions/inscription.html">Inscription</a>.</p>',7)])])}const u=a(n,[["render",s]]);export{g as __pageData,u as default};
